#!/usr/bin/env node
// Generates the package's icon modules from lut-icons.json (run build-manifest.mjs first):
//   src/icons/<name>.ts  `<Name>IconData` (the drawings) and `<Name>Icon` (its component)
//   src/index.ts         the components, `createLutIcon` and the types
//   src/data.ts          the `…Data` exports and `toSvgString`, for use outside React
// Generated files are rewritten on every run, formatted with the repo's Prettier; edit the scripts, never the output.
//
// Usage: node scripts/generate.mjs [--manifest <file>]

import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { format, resolveConfig } from 'prettier';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const i = process.argv.indexOf('--manifest');
const manifestPath = resolve(i > -1 ? process.argv[i + 1] : join(root, 'lut-icons.json'));
const src = join(root, 'src');
const iconsDir = join(src, 'icons');

// Output goes through the repo's Prettier config, so `pnpm format:check` passes on generated files too.
const write = async (file, text) =>
  writeFileSync(file, await format(text, { ...(await resolveConfig(file)), filepath: file }));

const HEADER = '// Generated by scripts/generate.mjs from lut-icons.json. Do not edit.\n';
const pascal = name => name.split('-').map(p => p[0].toUpperCase() + p.slice(1)).join('');

const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
const icons = manifest.map(entry => {
  const [name, { sizes }] = Object.entries(entry)[0];
  const masters = {};
  for (const s of sizes) {
    const m = Object.values(s)[0];
    masters[m.canvas] ??= {
      width: m.width,
      height: m.height,
      paths: m.innerSvgElements.map(({ type, ...p }) => p),
    };
  }
  return { name, id: `${pascal(name)}Icon`, masters };
});

// Duplicate ids would make two icons collide in the exports ("a-b" and "ab" are both AbIcon).
const seen = new Map();
for (const { name, id } of icons) {
  if (seen.has(id)) throw new Error(`"${name}" and "${seen.get(id)}" both become ${id}`);
  seen.set(id, name);
}

// An icon's names must not shadow the package's own exports: an icon "lut" would make `LutIconData`, the type.
const RESERVED = new Set(['LutIconCanvas', 'LutIconComponent', 'LutIconData', 'LutIconMaster', 'LutIconPath', 'LutIconProps', 'LutIconRotation', 'LutIconSize']);
for (const { name, id } of icons) {
  const clash = [id, `${id}Data`].find(n => RESERVED.has(n));
  if (clash) throw new Error(`icon "${name}" makes ${clash}, a name the package already exports; rename its artboards`);
}

rmSync(iconsDir, { recursive: true, force: true });
mkdirSync(iconsDir, { recursive: true });
for (const { name, id, masters } of icons) {
  await write(
    join(iconsDir, `${name}.ts`),
    HEADER +
      `import { createLutIcon } from '../createLutIcon';\nimport type { LutIconData } from '../types';\n\n` +
      `export const ${id}Data: LutIconData = ${JSON.stringify(masters, null, 2)};\n\n` +
      `export const ${id} = createLutIcon('${id}', ${id}Data);\n`,
  );
}

// One block of export-from lines ordered by module path, as the repo's lint (simple-import-sort) wants.
const collator = new Intl.Collator('en', { sensitivity: 'base', numeric: true });
const block = lines =>
  lines
    .sort((a, b) => collator.compare(a.match(/from '([^']+)'/)[1], b.match(/from '([^']+)'/)[1]))
    .join('\n') + '\n';

await write(
  join(src, 'index.ts'),
  HEADER +
    block([
      `export { createLutIcon, type LutIconComponent, type LutIconProps } from './createLutIcon';`,
      `export { LUT_ICON_SIZES } from './sizes';`,
      `export type { LutIconRotation, LutIconSize } from './types';`,
      ...icons.map(({ name, id }) => `export { ${id} } from './icons/${name}';`),
    ]),
);
await write(
  join(src, 'data.ts'),
  HEADER +
    block([
      `export { toSvgString } from './svgString';`,
      `export type { LutIconData, LutIconMaster, LutIconPath, LutIconRotation, LutIconSize } from './types';`,
      ...icons.map(({ name, id }) => `export { ${id}Data } from './icons/${name}';`),
    ]),
);

console.log(`${icons.length} icons → ${iconsDir}`);
if (readdirSync(iconsDir).length !== icons.length) throw new Error('icon files do not match the manifest');
